ext('c11_math_ch12',[
C("🎯","सीमा का विचार",["x किसी मान के पास जाए, बराबर नहीं","तब f(x) किस मान के पास जाता है","पास जाना और पहुँचना अलग बातें","सीमा केवल पास जाने का व्यवहार है"],"सीमा का विचार बहुत सरल है। मान लीजिए आप किसी दरवाज़े की ओर चल रहे हैं। जैसे-जैसे आप दरवाज़े के पास पहुँचते हैं, आपकी दूरी घटती जाती है। सीमा यह देखती है कि पास जाने पर फलन का मान किस संख्या के क़रीब पहुँच रहा है, भले ही आप ठीक दरवाज़े पर न पहुँचें। यह बहुत महत्वपूर्ण है, क्योंकि कई बार फलन उस बिंदु पर परिभाषित ही नहीं होता, पर आसपास के मान साफ़ बताते हैं कि वह किस ओर जा रहा है। यही सीमा है।"),
C("🔢","संख्याओं से अनुमान",["f(x) = x + 2, जब x → 1","x = 0.9, 0.99, 0.999 पर मान","x = 1.1, 1.01, 1.001 पर मान","दोनों ओर से मान 3 की ओर"],"एक उदाहरण से देखिए। फलन है एक्स जमा दो और एक्स को एक के पास ले जाना है। जब एक्स शून्य दशमलव नौ है, तो मान दो दशमलव नौ मिलता है। एक्स शून्य दशमलव निन्यानवे पर मान दो दशमलव निन्यानवे। एक्स शून्य दशमलव नौ सौ निन्यानवे पर मान और पास आता है। दूसरी ओर से भी, एक दशमलव एक पर तीन दशमलव एक और एक दशमलव शून्य एक पर तीन दशमलव शून्य एक। दोनों ओर से मान तीन के पास जा रहे हैं। इसलिए सीमा तीन है।"),
C("🕳️","जब फलन परिभाषित न हो",["f(x) = (x² − 1)/(x − 1)","x = 1 पर 0/0 रूप","पर सीमा मौजूद है","गुणनखंड करके x − 1 कटता है"],"सीमा का असली मज़ा तब आता है जब फलन उस बिंदु पर परिभाषित ही न हो। जैसे एक्स वर्ग ऋण एक भाग एक्स ऋण एक। एक्स बराबर एक रखने पर शून्य भाग शून्य मिलता है, जो अर्थहीन है। पर हम गुणनखंड करते हैं। अंश एक्स ऋण एक गुणा एक्स जमा एक है। एक्स ऋण एक कट जाता है और बचता है एक्स जमा एक। अब एक्स को एक के पास ले जाने पर मान दो मिलता है। यानी सीमा दो है, भले ही फलन एक पर परिभाषित नहीं। इसे अनिश्चित रूप हटाना कहते हैं।"),
C("⬅️","बायीं और दायीं सीमा समझिए",["x → a⁻ यानी a से छोटे मान","x → a⁺ यानी a से बड़े मान","दोनों बराबर तभी सीमा","अलग हों तो सीमा नहीं"],"सीमा दो तरफ़ से देखी जा सकती है। बायीं ओर से आने पर हम एक्स को ए से छोटे मानों से पास ले जाते हैं। इसे ए के ऊपर ऋण का चिह्न लगाकर लिखते हैं। दायीं ओर से आने पर एक्स ए से बड़े मानों से पास आता है, और ए पर धन का चिह्न लगता है। अगर दोनों तरफ़ से फलन एक ही मान के पास जाए, तो उस मान को सीमा कहते हैं। लेकिन अगर दोनों तरफ़ के मान अलग हों, तो सीमा मौजूद नहीं होती। जैसे कोई सीढ़ी जैसा फलन, जहाँ कूद होती है।"),
Q("f(x) = |x|/x के लिए x → 0 पर बायीं और दायीं सीमा निकालिए।","बायीं सीमा −1, दायीं सीमा +1। दोनों अलग हैं, इसलिए सीमा मौजूद नहीं।","एक मज़ेदार फलन देखिए, मॉड्यूलस एक्स भाग एक्स, जब एक्स शून्य के पास जाए। जब एक्स धनात्मक हो, तो मॉड्यूलस एक्स और एक्स बराबर होते हैं, इसलिए मान एक। जब एक्स ऋणात्मक हो, तो मॉड्यूलस एक्स बराबर ऋण एक्स होता है, इसलिए मान ऋण एक। यानी दायीं सीमा एक और बायीं सीमा ऋण एक है। दोनों अलग हैं, इसलिए शून्य पर सीमा मौजूद नहीं है। यह सीमा के प्रश्नों का बहुत प्रसिद्ध उदाहरण है।"),
Q("lim (x→2) (x² − 4)/(x − 2) निकालिए।","4","इस प्रश्न में सीधा रखने पर शून्य भाग शून्य आता है। इसलिए एक्स वर्ग ऋण चार का गुणनखंड कीजिए, एक्स ऋण दो गुणा एक्स जमा दो। एक्स ऋण दो ऊपर और नीचे कट जाता है। बचता है एक्स जमा दो। अब एक्स को दो के पास ले जाने पर मान चार मिलता है। इसलिए सीमा चार है। याद रखिए, गुणनखंड करना सीमा का सबसे पहला औज़ार है।"),
Q("lim (x→3) (x³ − 27)/(x − 3) निकालिए।","27","यहाँ घन का सूत्र काम आएगा। एक्स घन ऋण सत्ताईस बराबर एक्स ऋण तीन गुणा एक्स वर्ग जमा तीन एक्स जमा नौ। एक्स ऋण तीन कट जाता है। बचता है एक्स वर्ग जमा तीन एक्स जमा नौ। अब एक्स बराबर तीन रखिए। नौ जमा नौ जमा नौ बराबर सत्ताईस। इसलिए सीमा सत्ताईस है। दूसरा तरीक़ा भी है। मानक सीमा एक्स की घात एन ऋण ए की घात एन भाग एक्स ऋण ए का मान एन गुणा ए की घात एन ऋण एक होता है। यहाँ तीन गुणा नौ, यानी सत्ताईस।"),
C("✂️","परिमेयकरण की तरकीब",["वर्गमूल वाले प्रश्नों में","अंश और हर को संयुग्मी से गुणा","(a − b)(a + b) = a² − b²","इससे शून्य-शून्य रूप हटता है"],"जब सीमा में वर्गमूल हो, तब गुणनखंड सीधा नहीं चलता। तब हम परिमेयकरण की तरकीब अपनाते हैं। यानी अंश और हर को संयुग्मी से गुणा करते हैं। अगर अंश में वर्गमूल एक्स ऋण दो जैसा कुछ है, तो उसका संयुग्मी वर्गमूल एक्स जमा दो होता है। दोनों के गुणनफल से वर्गमूल हट जाता है और अंतर के वर्ग वाला सूत्र बनकर एक्स ऋण चार बचता है। फिर वह हर वाले एक्स ऋण चार से कट जाता है। यह तरकीब वर्गमूल वाली अधिकांश सीमाओं में काम करती है।"),
Q("lim (x→4) (√x − 2)/(x − 4) निकालिए।","1/4","एक्स बराबर चार रखने पर शून्य भाग शून्य आता है। अंश और हर को वर्गमूल एक्स जमा दो से गुणा कीजिए। अंश में वर्गमूल एक्स ऋण दो गुणा वर्गमूल एक्स जमा दो बनकर एक्स ऋण चार हो जाता है। अब ऊपर एक्स ऋण चार और नीचे एक्स ऋण चार गुणा वर्गमूल एक्स जमा दो है। एक्स ऋण चार कट गया। बचा एक भाग वर्गमूल एक्स जमा दो। एक्स चार पर वर्गमूल चार दो है, तो हर चार है। उत्तर एक चौथाई।"),
C("📐","त्रिकोणमितीय मानक सीमा",["sin x / x → 1 जब x → 0","x रेडियन में होना चाहिए","tan x / x → 1","(1 − cos x)/x² → 1/2"],"त्रिकोणमिति की सबसे प्रसिद्ध सीमा है, साइन एक्स भाग एक्स, जब एक्स शून्य के पास जाए, तो मान एक आता है। ध्यान दीजिए, यहाँ एक्स रेडियन में होना चाहिए, डिग्री में नहीं। इसी से टैन एक्स भाग एक्स की सीमा भी एक होती है। एक और उपयोगी सीमा है एक ऋण कोज्या एक्स भाग एक्स वर्ग, जिसका मान आधा है। इन तीनों को कंठस्थ कर लीजिए। कठिन दिखने वाले प्रश्नों में इन्हीं का रूप बदलकर कुछ पूछा जाता है, इसलिए अंश और हर में आवश्यक गुणा-भाग करके इन्हें बनाइए।"),
Q("lim (x→0) sin 3x / x निकालिए।","3","साइन तीन एक्स भाग एक्स को ऐसे लिखिए, तीन गुणा साइन तीन एक्स भाग तीन एक्स। अब जब एक्स शून्य के पास जाए, तो तीन एक्स भी शून्य के पास जाता है और साइन तीन एक्स भाग तीन एक्स की सीमा एक है। इसलिए पूरी सीमा तीन गुणा एक, यानी तीन है। तरकीब यह है कि साइन के भीतर जो है, वही हर में बना लीजिए, और जो गुणा बाहर आया, उसे सामने लिख दीजिए।"),
C("⚡","अवकलज: तात्कालिक परिवर्तन दर",["औसत चाल बनाम तात्क्षणिक चाल","बहुत छोटे अंतराल पर औसत चाल","f′(x) = lim (f(x+h) − f(x))/h","स्पर्श रेखा की ढलान"],"अब असली विषय अवकलज पर आइए। मान लीजिए आप गाड़ी में हैं और एक घंटे में साठ किलोमीटर चले, तो औसत चाल साठ हुई। पर किसी एक ख़ास पल की चाल क्या थी? इसके लिए हम बहुत छोटे समय का अंतराल लेते हैं और उसमें चली दूरी भाग समय देखते हैं। अंतराल को शून्य के पास ले जाने पर जो सीमा मिलती है, वही अवकलज है। ज्यामिति में यह वक्र की स्पर्श रेखा की ढलान है। इस तरह अवकलज परिवर्तन की दर बताता है, चाहे चाल हो, तापमान हो या क़ीमत।"),
Q("प्रथम सिद्धांत से f(x) = x² का अवकलज निकालिए।","2x","परिभाषा से शुरू कीजिए। एफ एक्स जमा एच ऋण एफ एक्स भाग एच। एफ एक्स जमा एच बराबर एक्स जमा एच का वर्ग, जो एक्स वर्ग जमा दो एक्स एच जमा एच वर्ग है। उसमें से एक्स वर्ग घटाइए, तो बचता है दो एक्स एच जमा एच वर्ग। हर एच से भाग देने पर दो एक्स जमा एच। अब एच को शून्य के पास ले जाइए, तो उत्तर दो एक्स। यही कारण है कि एक्स वर्ग का अवकलज दो एक्स होता है।"),
C("📘","मानक अवकलज और नियम",["x^n का अवकलज n·x^(n−1)","sin x का cos x, cos x का −sin x","eˣ का eˣ, ln x का 1/x","योग, गुणनफल, भागफल नियम"],"अवकलज बार-बार परिभाषा से नहीं निकालते। कुछ मानक अवकलज याद कर लेते हैं। एक्स की घात एन का अवकलज एन गुणा एक्स की घात एन ऋण एक। साइन एक्स का अवकलज कोज्या एक्स, और कोज्या एक्स का अवकलज ऋण साइन एक्स। ई की घात एक्स का अवकलज वही रहता है और लघुगणक एक्स का अवकलज एक भाग एक्स। फिर तीन नियम हैं। योग का अवकलज अलग-अलग अवकलजों का योग है। गुणनफल नियम में पहला का अवकलज गुणा दूसरा जमा पहला गुणा दूसरे का अवकलज। भागफल नियम में ऊपर वाले का अवकलज गुणा नीचे वाला ऋण ऊपर वाला गुणा नीचे का अवकलज, पूरा भाग नीचे वाले के वर्ग से।"),
Q("f(x) = x³ sin x का अवकलज निकालिए।","3x² sin x + x³ cos x","यह दो फलनों का गुणनफल है, इसलिए गुणनफल नियम लगेगा। पहला फलन एक्स घन, उसका अवकलज तीन एक्स वर्ग। दूसरा फलन साइन एक्स, उसका अवकलज कोज्या एक्स। नियम के अनुसार, पहले का अवकलज गुणा दूसरा, यानी तीन एक्स वर्ग साइन एक्स, जमा पहला गुणा दूसरे का अवकलज, यानी एक्स घन कोज्या एक्स। यही उत्तर है। ध्यान रखिए, गुणनफल का अवकलज दोनों के अवकलजों का गुणनफल नहीं होता।"),
Q("f(x) = (x² + 1)/x का अवकलज निकालिए।","1 − 1/x²","इसे भागफल नियम से निकाल सकते हैं, पर सरल तरीक़ा है पहले भाग देकर लिखना। एक्स वर्ग जमा एक भाग एक्स बराबर एक्स जमा एक भाग एक्स। अब एक्स का अवकलज एक और एक भाग एक्स का अवकलज ऋण एक भाग एक्स वर्ग। इसलिए उत्तर एक ऋण एक भाग एक्स वर्ग। कई बार प्रश्न को सरल बनाकर लिखने से नियम लगाने की ज़रूरत ही नहीं पड़ती, और ग़लती की संभावना घटती है।"),
],7)
